// Renders DiskNCM progress from status.json (published by the DiskNCM harness) and the
// live Brain stats from brain.json (generated by tools/generate_brain_graph.py).
// Refreshes status.json every 60 seconds and whenever the tab becomes visible again.
(() => {
  const todoCard = document.getElementById("todo-card");
  const todoList = document.getElementById("todo-list");
  const updated = document.getElementById("status-updated");
  const scoresCard = document.getElementById("scores-card") || document.getElementById("benchmarks");
  const scoreList = document.getElementById("score-list");
  const lbCard = document.getElementById("leaderboard");
  const lbList = document.getElementById("leaderboard-list");

  const TODO_LABEL = { todo: "To do", doing: "Doing", done: "Done", blocked: "Blocked" };
  const reduceMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;

  const el = (tag, className, text) => {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  };
  const fmtInt = (n) => Number(n).toLocaleString("en-US");

  function renderTodos(todos) {
    // status files from before to-dos existed have no "todos" key: hide the card
    todoCard.hidden = !Array.isArray(todos);
    if (todoCard.hidden) return;
    if (todos.length === 0) {
      todoList.replaceChildren(el("li", "todo todo--empty", "Nothing listed right now."));
      return;
    }
    todoList.replaceChildren(
      ...todos.map((t) => {
        const status = TODO_LABEL[t.status] ? t.status : "todo";
        const li = el("li", `todo todo--${status}`);
        li.append(el("span", "todo-title", t.title), el("span", `chip chip--${status}`, TODO_LABEL[status]));
        return li;
      })
    );
  }

  function renderScores(scores) {
    scoresCard.hidden = !Array.isArray(scores) || scores.length === 0;
    if (scoresCard.hidden) return;
    scoreList.replaceChildren(
      ...scores.map((s) => {
        const tr = el("tr", "score-row");
        const tdName = el("td", "score-name", s.benchmark || "");
        const tdBase = el("td", "score-base", s.base || "");
        const tdFull = el("td", "score-full");
        tdFull.append(el("span", "chip chip--result", s.harness || ""));
        const tdEv = el("td", "score-evidence", s.evidence || "");
        tr.append(tdName, tdBase, tdFull, tdEv);
        return tr;
      })
    );
  }

  function renderLeaderboard(rows) {
    lbCard.hidden = !Array.isArray(rows) || rows.length === 0;
    if (lbCard.hidden) return;
    lbList.replaceChildren(
      ...rows.map((r) => {
        const tr = el("tr", r.highlight ? "score-row score-row--highlight" : "score-row");
        tr.append(
          el("td", "score-base", String(r.rank ?? "")),
          el("td", "score-name", r.model || ""),
          el("td", "score-evidence", r.config || "")
        );
        const tdScore = el("td", "score-full");
        tdScore.append(el("span", r.highlight ? "chip chip--result" : "chip chip--done", r.score || ""));
        const tdNote = el("td", "score-evidence");
        if (r.url) {
          const a = el("a", "", r.note || "Source"); // never dump the raw URL into the cell
          a.href = r.url;
          a.target = "_blank";
          a.rel = "noopener noreferrer";
          tdNote.append(a);
        } else {
          tdNote.textContent = r.note || "";
        }
        tr.append(tdScore, tdNote);
        return tr;
      })
    );
  }

  function render(status) {
    renderScores(status.scores);
    renderLeaderboard(status.arc_agi_3_leaderboard);
    renderTodos(status.todos);
    const when = new Date(status.updated);
    updated.textContent = Number.isNaN(when.getTime()) ? "" : `Status updated ${when.toLocaleString()}`;
  }

  let hasRendered = false;
  async function refresh() {
    try {
      const res = await fetch(`status.json?t=${Date.now()}`, { cache: "no-store" });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      render(await res.json());
      hasRendered = true;
    } catch {
      // keep the last good render; try again on the next tick
      if (!hasRendered) updated.textContent = "Status is unavailable right now.";
    }
  }

  // ---- live Brain stats (brain.json)
  function countUp(elm, target, format) {
    if (reduceMotion) { elm.textContent = format(target); return; }
    const t0 = performance.now(), dur = 1400;
    const tick = (now) => {
      const k = Math.min(1, (now - t0) / dur);
      elm.textContent = format(Math.round(target * (1 - Math.pow(1 - k, 3))));
      if (k < 1) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  }

  async function renderBrainStats() {
    try {
      const res = await fetch("brain.json");
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const m = (await res.json()).meta;
      const notes = Number(m.notes) || 0;
      countUp(document.getElementById("stat-notes"), notes, fmtInt);
      countUp(document.getElementById("stat-edges"), Number(m.edges) || 0, (n) => `${(n / 1e6).toFixed(2)}M`);
      countUp(document.getElementById("stat-bytes"), Number(m.bytes) || 0, (n) => `${(n / 1e9).toFixed(2)} GB`);
      countUp(document.getElementById("stat-sources"), Number(m.sources) || 0, fmtInt);
      document.getElementById("hero-notes").textContent = fmtInt(notes);
      document.getElementById("nav-notes").textContent = fmtInt(notes);
    } catch {
      document.getElementById("hero-notes").textContent = "multi-million";
    }
  }

  // ---- copy buttons + section highlighting
  document.querySelectorAll(".copy-btn").forEach((btn) => {
    btn.addEventListener("click", async () => {
      try {
        await navigator.clipboard.writeText(btn.dataset.copy);
        btn.textContent = "Copied";
        setTimeout(() => (btn.textContent = "Copy"), 1600);
      } catch { /* clipboard unavailable */ }
    });
  });

  const navLinks = [...document.querySelectorAll(".site-nav a[href^='#']")];
  if (navLinks.length && "IntersectionObserver" in window) {
    const byId = Object.fromEntries(navLinks.map((a) => [a.getAttribute("href").slice(1), a]));
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          const a = byId[e.target.id];
          if (!a) return;
          if (e.isIntersecting) {
            navLinks.forEach((x) => x.removeAttribute("aria-current"));
            a.setAttribute("aria-current", "true");
          }
        });
      },
      { rootMargin: "-40% 0px -55% 0px" }
    );
    navLinks.forEach((a) => {
      const sec = document.getElementById(a.getAttribute("href").slice(1));
      if (sec) io.observe(sec);
    });
  }

  refresh();
  renderBrainStats();
  setInterval(refresh, 60_000);
  document.addEventListener("visibilitychange", () => document.visibilityState === "visible" && refresh());
})();
